import { chromium, type FullConfig } from '@playwright/test';

/**
 * Global setup: runs once before all test projects.
 * Currently a no-op — auth state is generated by the 'setup' project.
 */
async function globalSetup(_config: FullConfig) {
  if (process.env.E2E_ALLOW_MUTATIONS !== 'true') {
    throw new Error('Legacy browser suites can mutate backend data. Use npm run test:pwa for isolated tests, or explicitly opt in against a disposable staging project with E2E_ALLOW_MUTATIONS=true.');
  }
  // No-op — auth setup is handled by tests/auth.setup.ts
  return;
}

export default globalSetup;
